const MatchdayHome={
 nav(){return '<header class="md-nav"><a href="#" onclick="go(\'home\');return false" class="md-brand">'+clubAvatar12(my(),true)+'<span>ANCIENT<br>MANAGER</span></a><nav aria-label="Разделы клуба">'+[['home','ГЛАВНАЯ'],['squad','СОСТАВ'],['market','ТРАНСФЕРЫ'],['tactics','ТРЕНИРОВКИ'],['calendar','ТУРНИРЫ']].map(([key,label])=>'<button type="button" onclick="go(\''+key+'\')" '+(key==='home'?'aria-current="page"':'')+'>'+label+'</button>').join('')+'</nav><div class="md-date">'+esc(date(S.day))+'</div><div class="md-budget"><small>БЮДЖЕТ</small><b>'+esc(cash(S.budget))+'</b></div><button class="md-menu" type="button" onclick="go(\'menu21\')" aria-label="Все разделы">МЕНЮ ↗</button></header>';},
 home(){
  const team=my(),ps=roster(),r=readiness33C(),a=S.active,e=S.events.find(e=>e.id===a?.event)||nextEvent(),opponent=a&&S.teams[a.opponent],name=e?.name||'Новый сезон',words=name.split(' '),split=words.length>3?2:1,camp=e&&Camp4.plans()[Camp4.key(e.id)],events=S.events.filter(v=>!v.done&&!v.background51&&v.day>=S.day).sort((x,y)=>x.day-y.day),news=gameplayNewsNeon().slice(0,2),inviteEvent=Qualifiers.isRegional(e)?S.events.find(v=>v.id===e.qualifierFor):e;
  const action=a?"go('match')":e?.day<=S.day?'TournamentIntro52A.open()':"go('tactics')",label=a?'ОТКРЫТЬ МАТЧ':e?.day<=S.day?'НАЧАТЬ ТУРНИР':'ПОДГОТОВИТЬ КОМАНДУ';
  const stages=['Подготовка','Группы','Плей-офф','Финал'],stage=!a?0:a.schedule?.[a.cursor]?.championship?3:a.stage6==='playoffs'?2:1;
  return '<div class="md-home"><div class="md-content"><section class="md-feature"><div class="md-match '+(name.length>24?'md-long-title':'')+'"><div class="md-grain" aria-hidden="true"></div>'+'<div class="md-club-art" aria-hidden="true"><div class="md-art-word">'+esc(team.short)+'</div><div class="md-art-crest">'+clubAvatar12(team,false)+'</div><span>ONE CLUB. YOUR LEGACY.</span></div>'+'<div class="md-portrait-fade"></div><div class="md-match-copy"><span class="md-kicker">'+(a?'МАТЧ В ПРОЦЕССЕ':'БЛИЖАЙШИЙ ТУРНИР')+'</span><h1>'+esc(words.slice(0,split).join(' '))+'<br><span>'+esc(words.slice(split).join(' '))+'</span></h1><p class="md-tournament-meta">DOTA 2 / '+esc(e?.venue||'ТУРНИРНАЯ СЦЕНА')+'</p></div><div class="md-fixture"><div class="md-fixture-club">'+clubAvatar12(team,false)+'<b>'+esc(team.name)+'</b></div><span class="md-vs">'+(a?a.score.join(':'):'VS')+'</span><div class="md-fixture-club">'+(opponent?clubAvatar12(opponent,false):'<span class="md-draw">?</span>')+'<b>'+esc(opponent?.name||'Жеребьёвка впереди')+'</b></div><div class="md-fixture-info"><time>'+esc(e?date(e.day):date(S.day))+'</time><small>'+esc(a?.stage||'До старта '+Math.max(0,(e?.day??S.day)-S.day)+' дн.')+'</small><strong>'+esc(stages[stage])+'</strong></div></div>'+'</div><aside class="md-command"><div class="md-club-heading">'+clubAvatar12(team,false)+'<div><h2>'+esc(team.name)+'</h2><small>DOTA 2 ESPORTS CLUB / '+esc(team.region)+'</small></div></div><div class="md-metrics">'+[['OVR',r.ovr],['SIN',r.sin],['ФОРМА',r.form],['ЭНЕРГИЯ',r.energy]].map(([k,v],i)=>'<div><small>'+k+'</small><strong '+(i===3?'class="md-accent"':'')+'>'+Math.round(v)+(i===3?'<em>%</em>':'')+'</strong></div>').join('')+'</div><button class="md-next" type="button" onclick="advance()" '+(busy13?'disabled':'')+'>'+(a?'К МАТЧУ':e?.day<=S.day?'НАЧАТЬ ТУРНИР':'СЛЕДУЮЩИЙ ДЕНЬ')+' <span>»</span></button><div class="md-actions"><button type="button" onclick="'+action+'">'+label+' ↗</button>'+(!a&&e?'<button type="button" onclick="skipUpcomingTournament51B('+e.id+')" '+(busy13||S.practice13?'disabled':'')+'>ПРОПУСТИТЬ ТУРНИР</button>':'<button type="button" onclick="go(\'bracket\')">СЕТКА ТУРНИРА</button>')+'</div><div class="md-camp"><span>ПЛАН ПОДГОТОВКИ</span><strong>'+esc(camp?V4_CONFIG.camp.tiers[camp.tier].label:'Подготовка онлайн')+'</strong><button type="button" onclick="campEvent4='+(e?.id??'null')+';go(\'bootcamp\')">Открыть буткемп</button></div></aside></section><div class="md-lower"><section class="md-squad"><h2><i></i> ОСНОВНАЯ ПЯТЁРКА <button type="button" onclick="go(\'squad\')">Состав ↗</button></h2><div class="md-players">'+ps.map(p=>'<button type="button" onclick="profile('+p.id+')" aria-label="Профиль '+esc(p.name)+'"><div class="md-player-photo">'+portrait20(p)+'<b>'+Math.round(p.skill)+'</b></div><strong>'+esc(p.name)+'</strong><small>'+esc(ROLES[p.role])+'</small><div class="md-energy"><i style="--energy:'+clamp(100-p.fatigue)+'%"></i><span>'+Math.round(100-p.fatigue)+'%</span></div></button>').join('')+'</div></section><section class="md-schedule"><h2><i></i> БЛИЖАЙШИЕ 7 ДНЕЙ</h2>'+Array.from({length:7},(_,i)=>{const day=S.day+i,ev=events.find(v=>v.day===day);return '<button type="button" onclick="go(\''+(ev?'calendar':'tactics')+'\')"><time>'+esc(date(day).replace(/\s+202\d.*$/,''))+'</time><span>'+(ev?'<b>'+esc(ev.name)+'</b>':i===0?esc(trainingModes33[S.training]||'План подготовки'):'План тренировок')+'</span></button>';}).join('')+'</section><section class="md-news"><h2><i></i> ЖИЗНЬ КЛУБА</h2>'+(news.length?news.map(n=>'<article><time>'+esc(date(n.day))+'</time><h3>'+esc(n.text)+'</h3></article>').join(''):'<article><time>НОВАЯ ГЛАВА</time><h3>Сезон начинается с вашей команды.</h3><p>Первые результаты появятся здесь.</p></article>')+'<button type="button" onclick="go(\'history\')">История матчей ↗</button></section><section class="md-progress"><h2><i></i> ПУТЬ К ТРОФЕЮ</h2><strong>'+esc(e?.name||'Следующий турнир')+'</strong><p>'+esc(a?.stage||'Подготовка команды')+'</p><ol>'+stages.map((s,i)=>'<li class="'+(i===stage?'current':i<stage?'complete':'')+'"><i></i><span>'+s+'</span></li>').join('')+'</ol><div class="md-season"><small>СЕРИИ В КАРЬЕРЕ</small><b>'+S.wins+' <span>/</span> '+S.losses+'</b></div><button type="button" onclick="go(\'calendar\')">Календарь сезона ↗</button></section></div><div class="md-attention">'+alerts33C().map(v=>'<div><span>'+esc(v.text)+'</span><button type="button" onclick="'+v.action+'">'+esc(v.label)+' ↗</button></div>').join('')+'</div>'+(inviteEvent?.qualification&&inviteEvent.qualification.status!=='pending'?'<div class="md-qualification">'+qualifierCard(inviteEvent)+'</div>':'')+Background51.panel()+'<footer class="md-footer"><span>ANCIENT MANAGER / V6.0 A</span><div><button type="button" onclick="go(\'saves\')">Сохранения</button><button type="button" onclick="go(\'settings\')">Настройки</button><button type="button" onclick="go(\'menu21\')">Все разделы ↗</button></div></footer></div></div>';
 }
};
home=function(){return MatchdayHome.home();};
const renderBeforeMatchday6=render;
render=function(...args){
 const result=renderBeforeMatchday6(...args);
 if(!S||typeof document.createElement!=='function'||typeof document.querySelector!=='function'||!document.body?.classList)return result;
 document.body.classList.add('matchday');document.body.classList.toggle('matchday-home',page==='home');
 const app=$('app');app.classList.toggle('md-view',page!=='home');app.dataset.view=page;
 let header=document.getElementById('matchdayHeader6');if(!header){header=document.createElement('div');header.id='matchdayHeader6';header.className='md-home md-shell-header';document.querySelector('.shell21').insertBefore(header,document.querySelector('.workspace21'));}
 const primary=MatchdayHome.nav();
 const pages=PAGES.filter(p=>!['home','menu21'].includes(p[0]));
 header.innerHTML=primary+'<div class="md-routebar"><span>V6.0 A</span><span>'+esc(my().name)+'</span><small>'+esc(S.active?'Серия '+S.active.score.join(' : '):'Подготовка к турниру')+'</small><button type="button" onclick="go(\'saves\')">'+esc($('saveStatus').textContent)+'</button></div><nav class="md-section-nav" aria-label="Все вкладки">'+pages.map(([key,,label])=>'<button type="button" onclick="go(\''+key+'\')" '+(page===key?'aria-current="page"':'')+'>'+esc(label)+'</button>').join('')+'</nav>';
 for(const button of header.querySelectorAll('.md-nav nav button')){const key=button.getAttribute('onclick').match(/go\('([^']+)'\)/)?.[1];if(key===page)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}
 let tools=document.getElementById('matchdayTools6');if(!tools){tools=document.createElement('div');tools.id='matchdayTools6';tools.className='md-home md-page-toolbar';app.before(tools);}
 tools.hidden=page==='home';tools.innerHTML='<div><small>CLUB OPERATIONS / '+esc(my().short)+'</small><h1>'+esc(PAGES.find(p=>p[0]===page)?.[2]||({player:'Профиль игрока',match:'Матч-центр'})[page]||'Клуб')+'</h1></div><button type="button" class="md-next" onclick="advance()" '+($('advance').disabled?'disabled':'')+'>'+esc($('advance').textContent)+'</button>';
 if(typeof MutationObserver==='function'&&!MatchdayHome.saveObserver){MatchdayHome.saveObserver=new MutationObserver(()=>{const label=document.querySelector('#matchdayHeader6 .md-routebar button');if(label)label.textContent=$('saveStatus').textContent;});MatchdayHome.saveObserver.observe($('saveStatus'),{childList:true,characterData:true,subtree:true});}
 const current=header.querySelector('.md-section-nav [aria-current="page"]');if(current){const rail=current.parentElement;rail.scrollLeft=Math.max(0,current.offsetLeft-rail.clientWidth/2+current.clientWidth/2);}
 return result;
};
